     1	package hotel;
     2	
     3	import hotel.messages.EmailSender;
     4	import hotel.messages.SentMessages;
     5	import hotel.reports.OccupancyReport;
     6	import hotel.reports.RevenueReport;
     7	import hotel.reservations.PriceCalculator;
     8	import hotel.reservations.ReservationService;
     9	import hotel.reservations.ReservationStore;
    10	import hotel.rooms.Rooms;
    11	import hotel.web.HttpApi;
    12	import io.javalin.Javalin;
    13	
    14	/** Puts the inn's pieces together and runs the HTTP server. */
    15	public final class Hotel {
    16	
    17	    private final Javalin server;
    18	
    19	    public Hotel() {
    20	        Rooms rooms = new Rooms();
    21	        ReservationStore store = new ReservationStore();
    22	        SentMessages sentMessages = new SentMessages();
    23	        ReservationService reservations =
    24	                new ReservationService(rooms, store, new PriceCalculator(), new EmailSender(sentMessages));
    25	        HttpApi api = new HttpApi(
    26	                rooms, reservations, sentMessages, new OccupancyReport(rooms, store), new RevenueReport(store));
    27	        this.server = api.server();
    28	    }
    29	
    30	    /** Starts listening; port 0 picks a free port. Returns the port in use. */
    31	    public int start(int port) {
    32	        server.start(port);
    33	        return server.port();
    34	    }
    35	
    36	    public void stop() {
    37	        server.stop();
    38	    }
    39	
    40	    public static void main(String[] args) {
    41	        int port = Integer.parseInt(System.getenv().getOrDefault("PORT", "7070"));
    42	        new Hotel().start(port);
    43	    }
    44	}
     1	package hotel.reservations;
     2	
     3	import hotel.documents.ReservationReceipt;
     4	import hotel.messages.EmailSender;
     5	import hotel.notifications.DefaultListeners;
     6	import hotel.rooms.Room;
     7	import hotel.rooms.Rooms;
     8	import java.math.BigDecimal;
     9	import java.util.List;
    10	
    11	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
    12	public final class ReservationService {
    13	
    14	    private final Rooms rooms;
    15	    private final ReservationStore store;
    16	    private final PriceCalculator priceCalculator;
    17	    private final List<ReservationListener> listeners;
    18	
    19	    public ReservationService(
    20	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
    21	        this(rooms, store, priceCalculator, DefaultListeners.create(emailSender));
    22	    }
    23	
    24	    public ReservationService(
    25	            Rooms rooms,
    26	            ReservationStore store,
    27	            PriceCalculator priceCalculator,
    28	            List<ReservationListener> listeners) {
    29	        this.rooms = rooms;
    30	        this.store = store;
    31	        this.priceCalculator = priceCalculator;
    32	        this.listeners = List.copyOf(listeners);
    33	    }
    34	
    35	    public synchronized Reservation create(NewReservation request) {
    36	        if (!request.checkOut().isAfter(request.checkIn())) {
    37	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
    38	        }
    39	        if (request.guests() < 1) {
    40	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
    41	        }
    42	        Room room = rooms.find(request.roomNumber())
    43	                .orElseThrow(() -> new HotelException(
    44	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
    45	        if (request.guests() > room.capacity()) {
    46	            throw new HotelException(
    47	                    ErrorCode.CAPACITY_EXCEEDED,
    48	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
    49	        }
    50	        boolean roomTaken = store.all().stream()
    51	                .filter(existing -> existing.status() != ReservationStatus.CANCELLED)
    52	                .anyMatch(existing -> existing.overlaps(room.number(), request.checkIn(), request.checkOut()));
    53	        if (roomTaken) {
    54	            throw new HotelException(
    55	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
    56	        }
    57	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
    58	        Reservation reservation = new Reservation(store.nextId(), request, price);
    59	        store.save(reservation);
    60	        return reservation;
    61	    }
    62	
    63	    public Reservation find(long reservationId) {
    64	        return store.find(reservationId)
    65	                .orElseThrow(() -> new HotelException(
    66	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
    67	    }
    68	
    69	    /** The guest paid: the reservation is confirmed and the listeners are told. */
    70	    public synchronized Reservation confirm(long reservationId) {
    71	        Reservation reservation = find(reservationId);
    72	        if (reservation.status() != ReservationStatus.PENDING) {
    73	            throw notAllowed(reservation, "confirm");
    74	        }
    75	        reservation.confirmPayment();
    76	        Room room = roomOf(reservation);
    77	        listeners.forEach(listener -> listener.onConfirmed(reservation, room));
    78	        return reservation;
    79	    }
    80	
    81	    /**
    82	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
    83	     * reservation was never paid, so nothing comes back).
    84	     */
    85	    public synchronized Reservation cancel(long reservationId) {
    86	        Reservation reservation = find(reservationId);
    87	        if (reservation.status() != ReservationStatus.PENDING
    88	                && reservation.status() != ReservationStatus.CONFIRMED) {
    89	            throw notAllowed(reservation, "cancel");
    90	        }
    91	        BigDecimal refund = switch (reservation.ratePlan()) {
    92	            case STANDARD -> reservation.amountPaid();
    93	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
    94	        };
    95	        boolean wasPaid = reservation.status() == ReservationStatus.CONFIRMED;
    96	        reservation.cancel(refund);
    97	        if (wasPaid) {
    98	            Room room = roomOf(reservation);
    99	            listeners.forEach(listener -> listener.onConfirmedReservationCancelled(reservation, room));
   100	        }
   101	        return reservation;
   102	    }
   103	
   104	    public synchronized Reservation checkIn(long reservationId) {
   105	        Reservation reservation = find(reservationId);
   106	        if (reservation.status() != ReservationStatus.CONFIRMED) {
   107	            throw notAllowed(reservation, "check in");
   108	        }
   109	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
   110	        return reservation;
   111	    }
